import type { Language } from "@/i18n/translations";

/**
 * One "world quiz" general-knowledge question. Generated by
 * `scripts/build-quiz-data.mjs` (bundled files here, remote packs in
 * `content/quiz/<lang>/`) — never edit the JSON by hand.
 */
export interface WorldQuestion {
  /** Index (0–3) of the correct option in `options`. */
  answer: number;
  category: string;
  /** 1 easy · 2 medium · 3 hard. */
  difficulty: 1 | 2 | 3;
  /** Short "did you know" line shown after answering. */
  explanation: string;
  id: string;
  options: string[];
  question: string;
}

export interface WorldQuizFile {
  /** true = English stand-in for a missing translation (build-time marker). */
  fallback: boolean;
  lang: string;
  questions: WorldQuestion[];
}

// Lazy like the locale tables: only the active language's file is evaluated.
const loaders: Record<Language, () => WorldQuizFile> = {
  cs: () => require("./cs.json"),
  de: () => require("./de.json"),
  en: () => require("./en.json"),
  es: () => require("./es.json"),
  fr: () => require("./fr.json"),
  hi: () => require("./hi.json"),
  it: () => require("./it.json"),
  ja: () => require("./ja.json"),
  ko: () => require("./ko.json"),
  pl: () => require("./pl.json"),
  pt: () => require("./pt.json"),
  zh: () => require("./zh.json"),
};

export const worldQuizLanguages = Object.keys(loaders) as Language[];

/** The 100 bundled world questions in `language` (English if unknown). */
export function getBundledWorldQuestions(language: string): WorldQuestion[] {
  const loader = loaders[language as Language] ?? loaders.en;
  return loader().questions;
}

/** Whole bundled file (tests / diagnostics). */
export function getBundledWorldQuizFile(language: Language): WorldQuizFile {
  return loaders[language]();
}
